// Bare-metal IREE whole-model runner (F2 cycle campaign 2026-10-28), shared by resnet/tiny/smol.
// Inputs and the reference output are embedded (cfg.h + embed.S generated by gen_app.py). Inputs are
// uploaded once (resident); the entry function is invoked NINV times (0 = cold, then warm), each
// bracketed by rdcycle/rdinstret. After every invoke the outputs are compared with the reference
// (all elements, |a-r| <= atol + rtol*|r|) and an FNV-1a hash of the raw output bytes is printed.
// Lines: MODEL_BEGIN, INVOKE <i> cycles=<c> instret=<n>, CHECK <i> out=<k> n=<n> errors=<e> max_abs=<m> argmax=<a> fnv=<h>,
//        (PERFX_TRACE builds) TRACE_BEGIN <i> + PERFX rows, MODEL_DONE <fails>.
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "iree/async/util/proactor_pool.h"
#include "iree/base/api.h"
#include "iree/base/threading/thread.h"
#include "iree/hal/api.h"
#include "iree/hal/device.h"
#include "iree/hal/device_group.h"
#include "iree/hal/drivers/local_sync/sync_device.h"
#include "iree/hal/local/executable_loader.h"
#include "iree/hal/local/loaders/embedded_elf_loader.h"
#include "iree/modules/hal/module.h"
#include "iree/vm/api.h"
#include "iree/vm/bytecode/module.h"

#if defined(PERFX_TRACE) && PERFX_TRACE
void perfx_trace_reset(uint64_t origin);
void perfx_trace_dump(void);
#endif

typedef struct { const uint8_t* start; const uint8_t* end; int rank; iree_hal_dim_t shape[6]; iree_hal_element_type_t et; } min_t;
typedef struct { const uint8_t* start; const uint8_t* end; } mref_t;
#include "cfg.h"  // MODEL_NAME, ENTRY, NINV, NIN, INPUTS[], NOUT, REFS[], ATOL, RTOL, ELEM checks

// The VMFB lives in .vmfb_data (placed after .text by htif.ld, outside the medany +-2GB window for big
// models); the runner reaches it through 64-bit pointers stored in .rodata (same scheme as fixW tinyllama).
extern const uint8_t* const model_vmfb_start;
extern const uint8_t* const model_vmfb_end;

static iree_status_t create_device(iree_allocator_t host_allocator, iree_hal_device_t** out_device) {
  iree_hal_sync_device_params_t params;
  iree_hal_sync_device_params_initialize(&params);
  iree_hal_executable_loader_t* loader = NULL;
  IREE_RETURN_IF_ERROR(iree_hal_embedded_elf_loader_create(NULL, host_allocator, &loader));
  iree_string_view_t identifier = iree_make_cstring_view("local-sync");
  iree_hal_allocator_t* device_allocator = NULL;
  iree_status_t status = iree_hal_allocator_create_heap(identifier, host_allocator, host_allocator, &device_allocator);
  iree_async_proactor_pool_t* proactor_pool = NULL;
  if (iree_status_is_ok(status)) {
    iree_async_proactor_pool_options_t options = iree_async_proactor_pool_options_default();
    memset(&options.runner, 0, sizeof(options.runner));
    status = iree_async_proactor_pool_create(1, NULL, options, host_allocator, &proactor_pool);
  }
  iree_hal_device_create_params_t create_params = iree_hal_device_create_params_default();
  create_params.proactor_pool = proactor_pool;
  if (iree_status_is_ok(status)) {
    status = iree_hal_sync_device_create(identifier, &params, &create_params, 1, &loader, device_allocator,
                                         host_allocator, out_device);
  }
  iree_async_proactor_pool_release(proactor_pool);
  iree_hal_allocator_release(device_allocator);
  iree_hal_executable_loader_release(loader);
  return status;
}

#if defined(IREE_PLATFORM_GENERIC)
iree_status_t iree_thread_create(iree_thread_entry_t entry, void* entry_arg, iree_thread_create_params_t params,
                                 iree_allocator_t allocator, iree_thread_t** out_thread) {
  (void)entry; (void)entry_arg; (void)params; (void)allocator; *out_thread = NULL; return iree_ok_status();
}
void iree_thread_release(iree_thread_t* thread) { (void)thread; }
void iree_thread_yield(void) {}
void iree_thread_join(iree_thread_t* thread) { (void)thread; }
#endif

static inline uint64_t rd_cycle(void) { uint64_t c; __asm__ volatile("rdcycle %0" : "=r"(c)::"memory"); return c; }
static inline uint64_t rd_instret(void) { uint64_t c; __asm__ volatile("rdinstret %0" : "=r"(c)::"memory"); return c; }

static int check_outputs(iree_hal_device_t* device, iree_vm_list_t* outputs, int inv) {
  int fails = 0;
  for (int k = 0; k < NOUT; ++k) {
    iree_hal_buffer_view_t* v = iree_vm_list_get_buffer_view_assign(outputs, k);
    if (!v) { printf("CHECK %d out=%d missing\n", inv, k); ++fails; continue; }
    iree_device_size_t bytes = iree_hal_buffer_view_byte_length(v);
    size_t rbytes = (size_t)(REFS[k].end - REFS[k].start);
    uint8_t* h = (uint8_t*)malloc((size_t)bytes);
    if (!h) { printf("CHECK %d out=%d malloc\n", inv, k); ++fails; continue; }
    iree_status_t st = iree_hal_device_transfer_d2h(device, iree_hal_buffer_view_buffer(v), 0, h, bytes,
                                                    IREE_HAL_TRANSFER_BUFFER_FLAG_DEFAULT, iree_infinite_timeout());
    if (!iree_status_is_ok(st)) { iree_status_ignore(st); printf("CHECK %d out=%d d2h failed\n", inv, k); ++fails; free(h); continue; }
    uint64_t fnv = 1469598103934665603ull;
    for (iree_device_size_t i = 0; i < bytes; ++i) { fnv ^= h[i]; fnv *= 1099511628211ull; }
    long errors = 0; float max_abs = 0; long argmax = 0; long n = (long)(bytes / 4);
    if (rbytes != (size_t)bytes) {
      printf("CHECK %d out=%d size_mismatch bytes=%lu ref=%lu fnv=%016lx\n", inv, k, (unsigned long)bytes, (unsigned long)rbytes, (unsigned long)fnv);
      ++fails; free(h); continue;
    }
    const float* a = (const float*)h; const float* r = (const float*)REFS[k].start;
    for (long i = 0; i < n; ++i) {
      float e = fabsf(a[i] - r[i]);
      if (!isfinite(a[i]) || e > ATOL + RTOL * fabsf(r[i])) ++errors;
      if (e > max_abs) max_abs = e;
      if (a[i] > a[argmax]) argmax = i;
    }
    long rargmax = 0; for (long i = 0; i < n; ++i) if (r[i] > r[rargmax]) rargmax = i;
    printf("CHECK %d out=%d n=%ld errors=%ld max_abs=%g argmax=%ld ref_argmax=%ld fnv=%016lx\n", inv, k, n, errors,
           (double)max_abs, argmax, rargmax, (unsigned long)fnv);
    if (errors) ++fails;
    free(h);
  }
  fflush(stdout);
  return fails;
}

static iree_status_t Run(int* fails) {
  iree_vm_instance_t* instance = NULL;
  IREE_RETURN_IF_ERROR(iree_vm_instance_create(IREE_VM_TYPE_CAPACITY_DEFAULT, iree_allocator_system(), &instance));
  IREE_RETURN_IF_ERROR(iree_hal_module_register_all_types(instance));
  iree_hal_device_t* device = NULL;
  IREE_RETURN_IF_ERROR(create_device(iree_allocator_system(), &device));
  iree_hal_device_group_t* group = NULL;
  IREE_RETURN_IF_ERROR(iree_hal_device_group_create_from_device(device, iree_allocator_system(), &group));
  iree_vm_module_t* hal_module = NULL;
  IREE_RETURN_IF_ERROR(iree_hal_module_create(instance, iree_hal_module_device_policy_default(), group,
                                              IREE_HAL_MODULE_FLAG_SYNCHRONOUS, iree_hal_module_debug_sink_stdio(stderr),
                                              iree_allocator_system(), &hal_module));
  iree_hal_device_group_release(group);
  iree_const_byte_span_t vmfb = iree_make_const_byte_span(model_vmfb_start, (size_t)(model_vmfb_end - model_vmfb_start));
  iree_vm_module_t* bytecode_module = NULL;
  uint64_t t0 = rd_cycle();
  IREE_RETURN_IF_ERROR(iree_vm_bytecode_module_create(instance, IREE_VM_BYTECODE_MODULE_FLAG_NONE, vmfb,
                                                      iree_allocator_null(), iree_allocator_system(), &bytecode_module));
  iree_vm_context_t* context = NULL;
  iree_vm_module_t* modules[] = {hal_module, bytecode_module};
  IREE_RETURN_IF_ERROR(iree_vm_context_create_with_modules(instance, IREE_VM_CONTEXT_FLAG_NONE, 2, modules,
                                                           iree_allocator_system(), &context));
  uint64_t t1 = rd_cycle();
  iree_vm_module_release(hal_module);
  iree_vm_module_release(bytecode_module);
  iree_vm_function_t fn;
  IREE_RETURN_IF_ERROR(iree_vm_context_resolve_function(context, iree_make_cstring_view(ENTRY), &fn));
  iree_vm_list_t* inputs = NULL;
  IREE_RETURN_IF_ERROR(iree_vm_list_create(iree_vm_make_undefined_type_def(), NIN, iree_allocator_system(), &inputs));
  iree_hal_buffer_params_t params = {.type = IREE_HAL_MEMORY_TYPE_DEVICE_LOCAL, .usage = IREE_HAL_BUFFER_USAGE_DEFAULT};
  for (int j = 0; j < NIN; ++j) {
    iree_hal_buffer_view_t* v = NULL;
    IREE_RETURN_IF_ERROR(iree_hal_buffer_view_allocate_buffer_copy(
        device, iree_hal_device_allocator(device), INPUTS[j].rank, INPUTS[j].shape, INPUTS[j].et,
        IREE_HAL_ENCODING_TYPE_DENSE_ROW_MAJOR, params,
        iree_make_const_byte_span(INPUTS[j].start, (size_t)(INPUTS[j].end - INPUTS[j].start)), &v));
    iree_vm_ref_t r = iree_hal_buffer_view_move_ref(v);
    IREE_RETURN_IF_ERROR(iree_vm_list_push_ref_move(inputs, &r));
  }
  printf("MODEL_BEGIN %s entry=%s vmfb=%lu inputs=%d invokes=%d load_cycles=%lu\n", MODEL_NAME, ENTRY,
         (unsigned long)vmfb.data_length, NIN, NINV, (unsigned long)(t1 - t0));
  fflush(stdout);
  for (int it = 0; it < NINV; ++it) {
    iree_vm_list_t* outputs = NULL;
    IREE_RETURN_IF_ERROR(iree_vm_list_create(iree_vm_make_undefined_type_def(), NOUT, iree_allocator_system(), &outputs));
#if defined(PERFX_TRACE) && PERFX_TRACE
    perfx_trace_reset(rd_cycle());
#endif
    uint64_t i0 = rd_instret(), c0 = rd_cycle();
    IREE_RETURN_IF_ERROR(iree_vm_invoke(context, fn, IREE_VM_INVOCATION_FLAG_NONE, NULL, inputs, outputs, iree_allocator_system()));
    uint64_t c1 = rd_cycle(), i1 = rd_instret();
    printf("INVOKE %d cycles=%lu instret=%lu\n", it, (unsigned long)(c1 - c0), (unsigned long)(i1 - i0));
    fflush(stdout);
#if defined(PERFX_TRACE) && PERFX_TRACE
    printf("TRACE_BEGIN %d\n", it); perfx_trace_dump();
#endif
    *fails += check_outputs(device, outputs, it);
    iree_vm_list_release(outputs);
  }
  iree_vm_list_release(inputs);
  iree_vm_context_release(context);
  iree_hal_device_release(device);
  iree_vm_instance_release(instance);
  return iree_ok_status();
}

int main(void) {
  int fails = 0;
  iree_status_t status = Run(&fails);
  if (!iree_status_is_ok(status)) {
    printf("MODEL_FAILED: "); iree_status_fprint(stdout, status); printf("\n"); fflush(stdout);
    iree_status_free(status); return 1;
  }
  printf("MODEL_DONE %d\n", fails); fflush(stdout);
  return fails ? 2 : 0;
}
